  "summary": "梗源：teh tarik(拉茶) 是马来/新加坡国民奶茶，以高空反复倒拉出泡沫著称，「Teh Tarik satu!」是嘛嘛档日常点单声，象征多元文化融合。印花机会：做拉茶倾倒泡沫动态线条+茶杯图案款，国民认同度极高、餐饮周边强，是马市场视觉常青款。（印选 11-09 热点重排上架：库内真实历史热点复用，非新研究。）（印选 11-18 热点重排上架：库内真实历史热点复用，非新研究。）",
